arguments.command:
cd /app/submission && python3 -m py_compile planner.py && echo "compiles" && python3 - <<'EOF'
import ast, sys
src = open('/app/submission/planner.py').read()
tree = ast.parse(src)
names = set()
for node in ast.walk(tree):
    if isinstance(node, ast.Name): names.add(node.id)
    if isinstance(node, ast.Attribute):
        n = node
        while isinstance(n, ast.Attribute): n = n.value
        if isinstance(n, ast.Name): names.add(n.id)
imports = []
for node in ast.walk(tree):
    if isinstance(node, ast.Import):
        for a in node.names: imports.append(a.asname or a.name.split('.')[0])
    if isinstance(node, ast.ImportFrom):
        for a in node.names: imports.append(a.asname or a.name)
print("unused imports:", [i for i in imports if i not in names])
print("lines:", src.count(chr(10)))
EOF
rm -rf /app/submission/__pycache__; ls -la /app/submission/
